use vstd::prelude::*;

verus! {

    // Specification for the less function
    fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool>
        requires
            a.len() == b.len(), // Precondition: both arrays must have the same length
        ensures
            result.len() == a.len() && // Postcondition: result has the same length as input arrays
            forall|i: nat| (i < a.len() as nat) ==> (result[i as usize] <==> (a[i as usize] < b[i as usize])) // Postcondition: result[i] is true if a[i] < b[i]
    {
        let mut result: Vec<bool> = Vec::new();
        let len = a.len();
        result.resize(len, false); // Initialize result with the same length as a and b

        let mut idx: usize = 0;
        while idx < len
            invariant
                idx <= len,
                result.len() == len,
                forall|i: nat| (i < idx as nat) ==> (result[i as usize] <==> (a[i as usize] < b[i as usize])), // Maintain the correctness of the result up to idx
            decreases len - idx,
        {
            result[idx] = a[idx] < b[idx]; // Compare elements and store the result
            idx = idx + 1; // Move to the next index
        }
        result // Return the result vector
    }
}
